/* Server-backed application. Legacy prototype scripts are retained as reference, not executed. */
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let currentUser=null,viewRole='employee',page='首页',state=null,taskFilter='全部',spaceFilter='',evalFrom='',evalTo='',query='',currentTask=null,poll=null,selectedTaskTab=0;
const roleNames=['产品研究员','需求分析师','项目交付助理','数据分析师'];
const menuIcons=['home','team','task','grid','book','chart','settings','org','user'];
const menuNames=['首页','数字员工','任务中心','工作空间','知识库','效果评估','运营管理','组织设置','用户管理'];
const iconPaths={home:'<path d="m3 10 9-7 9 7v10h-6v-7H9v7H3z"/>',team:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m2-17a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 5v2"/>',task:'<rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 4V2h6v2M8 11l2 2 5-5M9 17h6"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',book:'<path d="M4 3h12l4 4v14H4zM15 3v5h5M8 12h8M8 16h8"/>',chart:'<path d="M3 3v18h18M7 17v-5m5 5V7m5 10V4"/>',settings:'<path d="m9 3-1 3-3 1-2 4 2 2v4l4 2 3-1 3 1 4-2v-4l2-2-2-4-3-1-1-3z"/><circle cx="12" cy="12" r="3"/>',org:'<rect x="8" y="2" width="8" height="5" rx="1"/><path d="M12 7v5M4 16v-4h16v4"/><rect x="1" y="16" width="6" height="5" rx="1"/><rect x="9" y="16" width="6" height="5" rx="1"/><rect x="17" y="16" width="6" height="5" rx="1"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M4 21v-3a8 8 0 0 1 16 0v3"/>',bell:'<path d="M5 17h14l-2-3V9a5 5 0 0 0-10 0v5zM10 21h4M12 2v2"/>'};
const svgIcon=(name='user')=>`<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[name]||iconPaths.user}</svg>`;
const adminMode=()=>currentUser?.role==='admin';
const nameOf=id=>state?.directory.find(u=>u.id===Number(id))?.name||'已停用人员';
const employeeOf=id=>state?.employees.find(e=>e.id===id);
const stamp=s=>s?new Date(s).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'—';
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const empty=(s='暂无记录')=>`<div class="empty">${esc(s)}</div>`;
const badge=s=>`<span class="status ${s==='已完成'||s==='在岗'||s==='已发布'?'done':s==='待验收'||s==='待审核'?'wait':'queue'}">${esc(s)}</span>`;
const head=(title,sub,button='',fn='')=>`<div class="pagehead"><div><h2>${esc(title)}</h2><p>${esc(sub)}</p></div>${button?`<button class="primary" onclick="${fn}">${esc(button)}</button>`:''}</div>`;
function heading(...args){return head(...args)}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
function modal(html){$('#dialogBody').innerHTML=html;if(!$('#dialog').open)$('#dialog').showModal()}
function closeModal(){currentTask=null;$('#dialog').close()}
function formError(e){const el=$('#form-error');if(el)el.textContent=e.message;else toast(e.message)}
function table(headers,body){return `<div class="table-scroll"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${body||`<tr><td colspan="${headers.length}">${empty()}</td></tr>`}</tbody></table></div>`}
function field(label,name,value='',type='text',required=false){return `<label>${esc(label)}${required?' *':''}<input type="${type}" name="${name}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'step="any"':''}></label>`}
function area(label,name,value='',required=false){return `<label>${esc(label)}${required?' *':''}<textarea name="${name}" ${required?'required':''}>${esc(value)}</textarea></label>`}
function select(label,name,options,value=''){return `<label>${esc(label)}<select name="${name}">${options.map(([id,text])=>`<option value="${esc(id)}" ${String(id)===String(value)?'selected':''}>${esc(text)}</option>`).join('')}</select></label>`}
function checks(label,name,options,values=[]){return `<fieldset><legend>${esc(label)}</legend><div class="check-grid">${options.map(([id,text])=>`<label class="check"><input type="checkbox" name="${name}" value="${esc(id)}" ${values.map(String).includes(String(id))?'checked':''}>${esc(text)}</label>`).join('')}</div></fieldset>`}
function formDialog(title,body,submit){currentTask=null;modal(`<h2>${esc(title)}</h2><form id="main-form">${body}<p id="form-error" class="error" role="alert"></p><div class="modalfoot"><button type="button" onclick="closeModal()">取消</button><button class="primary" id="save-button">保存</button></div></form>`);$('#main-form').onsubmit=async e=>{e.preventDefault();const b=$('#save-button');b.disabled=true;try{await submit(new FormData(e.target))}catch(err){formError(err)}finally{if(b.isConnected)b.disabled=false}}}
async function refresh(){state=await api('/api/bootstrap');currentUser=state.user;viewRole=currentUser.role}
async function render(){if(!currentUser)return;try{await refresh();drawShell();if(page==='用户管理'){await baseRenderUsers();return}const renderers={'首页':homePage,'数字员工':employeesPage,'任务中心':tasksPage,'工作空间':spacesPage,'知识库':knowledgePage,'效果评估':evaluationPage,'运营管理':operationsPage,'组织设置':organizationPage};$('#content').innerHTML=(renderers[page]||homePage)();if(page==='首页')applyHomeDesign();}catch(e){$('#content').innerHTML=`<section class="panel"><h2>加载失败</h2><p>${esc(e.message)}</p><button onclick="render()">重试</button></section>`}}
function drawShell(){const allowed=adminMode()?menuNames:menuNames.filter(n=>!['运营管理','组织设置','用户管理'].includes(n));if(!allowed.includes(page))page='首页';$('#nav').innerHTML=allowed.map(n=>`<button class="${page===n?'active':''}" aria-label="${n}" onclick="go('${n}')"><span class="nav-symbol">${svgIcon(menuIcons[menuNames.indexOf(n)])}</span><span>${n==='首页'?(adminMode()?'管理工作台':'我的工作台'):n}</span>${n==='任务中心'&&state.tasks.some(t=>!['已完成','已取消'].includes(t.status))?`<i>${state.tasks.filter(t=>!['已完成','已取消'].includes(t.status)).length}</i>`:''}</button>`).join('');$('#crumb').textContent=page;$('.aside-foot').innerHTML=esc(currentUser.name)+'<br><small>本地试用 · 服务端存储</small>';$('.topline>span:last-child').textContent=state.model.configured?'模型已配置 · 单任务运行':'模型待配置 · 可人工交付';const noticeCount=state.notices.filter(n=>!n.read).length;$('#notice').innerHTML=svgIcon('bell')+(noticeCount?`<i>${noticeCount}</i>`:'');$('#notice').setAttribute('aria-label','通知，'+noticeCount+'条未读');$('#notice').onclick=notices;let box=$('#user-menu');if(!box){box=document.createElement('div');box.id='user-menu';document.querySelector('header').append(box);const av=$('header>.avatar');if(av){av.nextElementSibling.style.display='none';av.style.display='none'}}box.innerHTML=`<b>${esc(currentUser.name)}</b><small>${adminMode()?'管理员':'员工'}</small><button onclick="logoutUser()">退出登录</button>`;document.body.classList.toggle('home-page',page==='首页');}
async function go(n){page=n;query='';$('#search').value='';await render()}
function taskList(items,compact=false){return table(['任务 / 工作空间','数字员工','期限','状态 / 下一步','操作'],items.map(t=>{const due=t.due<today()&&!['已完成','已取消'].includes(t.status);const sp=state.spaces.find(s=>s.id===t.space_id);return `<tr><td><button class="link task-link" onclick="detail('${t.id}')">${esc(t.title)}</button><small>${esc(sp?.name||'独立任务')} · 发起 ${esc(nameOf(t.requester_id))}</small></td><td>${esc(employeeOf(t.employee_id)?.name||t.employee_snapshot.name)}</td><td class="${due?'error':''}">${esc(t.due)}${due?' · 逾期':''}</td><td>${badge(t.status)}${t.running?' <small>执行中</small>':''}<small>${t.blocked?esc(t.blocked):t.status==='待验收'?'待 '+esc(nameOf(t.reviewer_id))+' 验收':t.status==='已完成'?'业务反馈：'+esc(t.feedback):'负责人 '+esc(nameOf(t.owner_id))}</small></td><td><button onclick="detail('${t.id}')">查看</button></td></tr>`}).join(''))}
function metrics(items){return `<div class="metric-grid">${items.map(([label,value,fn,note])=>`<button class="metric-card" ${fn?`onclick="${fn}"`:''}><small>${esc(label)}</small><b>${esc(value)}</b><span>${esc(note||'')}</span></button>`).join('')}</div>`}
function homePage(){const ts=state.tasks,pending=ts.filter(t=>t.status==='待验收'&&t.reviewer_id===currentUser.id);const available=state.employees.filter(e=>e.status==='在岗'&&(adminMode()||e.assignees.includes(currentUser.id)));const due=ts.filter(t=>!['已完成','已取消'].includes(t.status)&&(t.due<=today()||t.reviewer_id===currentUser.id&&t.status==='待验收'));return `${head(adminMode()?'管理工作台':'我的工作台',`${currentUser.name}，欢迎回来。任务、成果与验收按统一台账同步。`,'＋ 发起任务','newTask()')}${metrics([['总任务数',ts.length,"filterTasks('全部')",'当前授权范围'],['进行中',ts.filter(t=>t.status==='进行中').length,"filterTasks('进行中')",'包含执行受阻任务'],['待我验收',pending.length,"filterTasks('待我验收')",'仅限指定验收人'],['已完成',ts.filter(t=>t.status==='已完成').length,"filterTasks('已完成')",'验收完成；采纳另记']])}<div class="workspace-layout"><div><section class="system-hero"><div><span>专业创造财富 · 责任成就未来</span><h1>数字员工，让专业创造更大价值</h1><p>研究更深入 · 需求更清晰 · 交付更高效 · 判断更有依据</p></div><b>AI + 人的专业判断</b></section><section class="panel"><div class="section-head"><h2>我的数字员工</h2><button class="link" onclick="go('数字员工')">全部员工 →</button></div>${employeeCards([...available].sort((a,b)=>roleNames.indexOf(a.role_type)-roleNames.indexOf(b.role_type)).slice(0,4))}</section><section class="panel"><div class="section-head"><h2>近期任务进展</h2><button class="link" onclick="go('任务中心')">全部任务 →</button></div>${taskList(ts.slice(0,6),true)}</section><section class="panel"><h2>知识与工具</h2><div class="resource-grid">${state.knowledge.filter(k=>k.status==='已发布').slice(0,4).map(k=>`<button onclick="knowledgeDetail('${k.id}')"><b>${esc(k.name)}</b><small>知识 V${k.version} · ${esc(k.source)}</small></button>`).join('')||empty('尚无已发布知识，可上传任务材料或提交知识审核')}${state.tools.filter(t=>t.status==='已发布').map(t=>`<div class="resource-card"><b>${esc(t.name)}</b><small>${esc(t.description)}</small></div>`).join('')}</div></section></div><div><section class="panel"><h2>今日待办</h2>${due.map(t=>`<div class="file"><button class="link" onclick="detail('${t.id}')">${esc(t.title)}</button><small>${t.due<today()?'已逾期':t.due===today()?'今日到期':'待我验收'} · ${esc(t.due)}</small></div>`).join('')||empty('今日无到期或待验收事项')}</section><section class="panel"><h2>通知与动态</h2>${state.notices.slice(0,5).map(n=>`<div class="file"><button class="link" onclick="openNotice(${n.id})">${n.read?'':'● '}${esc(n.title)}</button><small>${stamp(n.at)}</small></div>`).join('')||empty('暂无通知')}</section><section class="panel"><h2>热门模板</h2>${state.templates.filter(t=>t.status==='已发布').map(t=>`<div class="file"><b>${esc(t.name)}</b><small>${esc(t.role_type)} · V${t.version}</small><button onclick="newTask(null,'${t.id}')">使用模板</button></div>`).join('')}</section>${adminMode()?`<section class="panel"><h2>接入情况</h2><p>用户与业务数据库：已连接</p><p>LangGraph：本地执行</p><p>模型：${state.model.configured?esc(state.model.model):'待配置'}</p><p>文件：本地存储</p><button onclick="go('运营管理')">配置模型与能力</button></section>`:''}</div></div>`}
function employeeCards(list){return `<div class="employee-grid">${list.map((e,i)=>`<article class="employee-card" data-role="${roleNames.indexOf(e.role_type)}"><div class="employee-card-top">${employeeAvatar(e)}<div><h3>${esc(e.name)}</h3><small>${esc(e.code)} · ${esc(e.department)}</small></div>${badge(e.status)}</div><p>${esc(e.mission)}</p><small>负责人：${esc(nameOf(e.owner_id))} · ${esc(state.tasks.some(t=>t.employee_id===e.id&&t.running)?'忙碌':'空闲')}</small><div class="card-actions"><button onclick="employeeDetail('${e.id}')">岗位详情</button><button onclick="clarify('${e.id}')">澄清需求</button><button class="primary" onclick="newTask('${e.id}')" ${e.status!=='在岗'?'disabled':''}>发起任务</button></div></article>`).join('')||empty('暂无获分配员工，请联系管理员分配')}</div>`}
function employeesPage(){const list=state.employees.filter(e=>!query||[e.name,e.role_type,e.department,e.mission].join(' ').includes(query));return head('数字员工','了解岗位、边界与交付要求，选择已授权的协作对象。')+employeeCards(list)}
function employeeDetail(id){const e=employeeOf(id);modal(`<div class="avatar-detail-heading">${employeeAvatar(e)}<h2>${esc(e.name)}</h2></div><div class="detail"><p>${badge(e.status)} · 工号 ${esc(e.code)} · 档案 V${e.version}</p><h3>岗位使命</h3><p>${esc(e.mission)}</p><h3>核心输出</h3><p>${esc(e.output)}</p><h3>职责边界</h3><p>${esc(e.boundary)}</p><h3>质量标准</h3><p>${esc(e.quality)}</p><p>人类负责人：${esc(nameOf(e.owner_id))}</p><h3>可用能力版本</h3>${state.skills.filter(s=>s.role_type===e.role_type&&s.status==='已发布').map(s=>`<p>${esc(s.name)} · V${s.version}</p>`).join('')||'<p>暂无已发布技能</p>'}<p>历史任务：${state.tasks.filter(t=>t.employee_id===id).length}；没有样本时不推算质量。</p></div><div class="modalfoot"><button onclick="closeModal()">关闭</button><button class="primary" onclick="closeModal();newTask('${id}')">发起任务</button></div>`)}
function manualClarify(id){formDialog('澄清需求并转为任务',`<p class="detail">请先明确以下内容，确认后将带入任务草稿；本表单不会冒充模型对话。</p>${area('希望解决的问题','goal','',true)}${area('已有材料与限制','input')}${area('什么结果算完成','criteria','结论有依据，结构完整，缺失信息单独列示。',true)}`,async f=>{closeModal();newTask(id,'',{goal:f.get('goal'),input:f.get('input'),criteria:f.get('criteria')})})}
function filterTasks(s){taskFilter=s;page='任务中心';render()}
function tasksPage(){let ts=state.tasks.filter(t=>(!spaceFilter||t.space_id===spaceFilter)&&(!query||[t.title,t.goal,employeeOf(t.employee_id)?.name].join(' ').includes(query)));if(taskFilter==='待我验收')ts=ts.filter(t=>t.status==='待验收'&&t.reviewer_id===currentUser.id);else if(taskFilter==='我发起')ts=ts.filter(t=>t.requester_id===currentUser.id);else if(taskFilter==='已逾期')ts=ts.filter(t=>t.due<today()&&!['已完成','已取消'].includes(t.status));else if(taskFilter!=='全部')ts=ts.filter(t=>t.status===taskFilter);return head('任务中心','任务、执行、成果与验收分别留痕；完成交付不等于业务已采纳。','＋ 创建任务','newTask()')+`<section class="panel"><div class="tabs">${['全部','我发起','待我验收','草稿','排队中','进行中','待验收','已完成','已取消','已逾期'].map(s=>`<button class="${s===taskFilter?'selected':''}" onclick="filterTasks('${s}')">${s}</button>`).join('')}</div><div class="toolbar"><label>工作空间<select onchange="spaceFilter=this.value;render()"><option value="">全部空间</option>${state.spaces.map(s=>`<option value="${s.id}" ${spaceFilter===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><span>${ts.length} 项任务</span><button onclick="legacyImport()">导入旧浏览器任务</button><button onclick="exportTasks()">导出台账</button></div>${taskList(ts)}</section>`}
async function newTask(employeeId=null,templateId='',prefill={}){const e=state.employees.filter(e=>e.status==='在岗'&&(adminMode()||e.assignees.includes(currentUser.id)));if(!e.length)return toast('暂无可用员工，请联系管理员分配');const template=state.templates.find(t=>t.id===templateId);if(template&&!employeeId)employeeId=e.find(x=>x.role_type===template.role_type)?.id;let uploaded=[];const requestKey=crypto.randomUUID();formDialog('创建任务 · 确认后提交',`<div class="form-grid">${field('任务名称','title',prefill.title||template?.name||'','text',true)}${select('负责数字员工','employee_id',e.map(x=>[x.id,x.name]),employeeId||e[0].id)}</div>${area('业务目标','goal',prefill.goal||template?.goal||'',true)}${area('范围与排除项','scope')}${area('背景与输入说明','input',prefill.input||'')}${area('验收标准（每行一项）','criteria',prefill.criteria||template?.criteria||'交付结构完整\n事实有来源，判断与待验证项分开\n关键结论由人类复核',true)}<div class="form-grid">${select('验收人','reviewer_id',state.directory.map(u=>[u.id,u.name]),currentUser.id)}${select('业务负责人','owner_id',state.directory.map(u=>[u.id,u.name]),currentUser.id)}${field('截止日期','due',today(),'date',true)}${select('优先级','priority',[['普通','普通'],['高','高'],['紧急','紧急']])}${select('工作空间（可选）','space_id',[['','独立任务'],...state.spaces.filter(s=>s.status!=='已归档').map(s=>[s.id,s.name])],spaceFilter)}${field('费用上限（元，可留空）','budget','','number')}</div>${area('过去期限例外原因（如适用）','past_due_reason')}${checks('选择已发布知识（可选）','knowledge_ids',state.knowledge.filter(k=>k.status==='已发布').map(k=>[k.id,`${k.name} V${k.version}`]))}${checks('依赖已完成任务（可选）','dependencies',state.tasks.filter(t=>t.status==='已完成').map(t=>[t.id,t.title]))}<label>上传材料（单文件≤10MB；TXT/MD/CSV/JSON/DOCX/XLSX/PDF）<input type="file" id="task-files" multiple></label><p id="upload-result" class="muted"></p><label class="check"><input type="checkbox" name="draft">先保存为草稿</label><div class="noticebar">请确认目标、材料及验收标准。模型仅使用本次输入，未接入自动联网搜索或代码执行。</div>`,async f=>{const data=Object.fromEntries(f);data.file_ids=uploaded;data.knowledge_ids=f.getAll('knowledge_ids');data.dependencies=f.getAll('dependencies');data.reviewer_id=Number(data.reviewer_id);data.owner_id=Number(data.owner_id);data.budget=data.budget?Number(data.budget):null;data.draft=f.has('draft');data.template_id=templateId;const task=await api('/api/tasks',{method:'POST',headers:{'Idempotency-Key':requestKey},body:JSON.stringify(data)});closeModal();await render();await detail(task.id)});$('#task-files').onchange=async ev=>{const b=$('#save-button');b.disabled=true;try{for(const file of ev.target.files){const f=new FormData();f.append('file',file);const r=await fetch('/api/upload',{method:'POST',body:f});const data=await r.json();if(!r.ok)throw Error(data.detail);uploaded.push(data.id);$('#upload-result').textContent+=`${data.name} 已上传${data.truncated?'（提取文字已截断）':''}； `}}catch(e){formError(e)}finally{b.disabled=false}}}
async function detail(id){try{const t=await api('/api/tasks/'+id);if(currentTask?.id!==id)selectedTaskTab=0;currentTask=t;const editor=[t.requester_id,t.owner_id].includes(currentUser.id),reviewer=t.reviewer_id===currentUser.id,latest=t.artifacts.at(-1);const actions=state.actions.filter(a=>a.task_id===id);modal(`<div class="task-heading"><div><h2>${esc(t.title)}</h2><small>${esc(id.slice(0,12))} · 契约 V${t.contract_version} · ${badge(t.status)}</small></div><button onclick="detail('${id}')">刷新</button></div>${t.blocked?`<div class="noticebar error">${esc(t.blocked)}</div>`:''}<div class="tabs detail-tabs">${['任务要求','执行过程','交付成果','验收记录','业务反馈'].map((s,i)=>`<button class="${i===0?'selected':''}" onclick="taskTab(${i},this)">${s}</button>`).join('')}</div><section class="task-tab"><div class="facts"><span>数字员工：${esc(employeeOf(t.employee_id)?.name||t.employee_snapshot.name)}</span><span>发起人：${esc(nameOf(t.requester_id))}</span><span>业务负责人：${esc(nameOf(t.owner_id))}</span><span>验收人：${esc(nameOf(t.reviewer_id))}</span><span>截止：${esc(t.due)}</span><span>优先级：${esc(t.priority)}</span></div><h3>业务目标</h3><p class="prewrap">${esc(t.goal)}</p><h3>范围与背景</h3><p class="prewrap">${esc(t.scope+'\n'+t.input)}</p><h3>验收标准</h3><p class="prewrap">${esc(t.criteria)}</p><h3>材料与版本</h3>${t.file_ids.map(fid=>`<a class="file-link" href="/api/files/${fid}?task_id=${t.id}" target="_blank">下载输入文件 ${fid.slice(0,8)}</a>`).join('')||'<p>未附加文件</p>'}<p>模板：${esc(t.template_snapshot.name||'未使用模板')} ${t.template_snapshot.version?'V'+t.template_snapshot.version:''}</p><p>技能：${esc(t.skill_snapshot.name||'默认步骤')} ${t.skill_snapshot.version?'V'+t.skill_snapshot.version:''}</p><p>知识快照：${t.knowledge_versions.map(k=>esc(k.id.slice(0,8))+' V'+k.version).join('、')||'未引用'}</p><h3>契约变更</h3><pre>${esc(JSON.stringify(t.contract_history,null,2))}</pre></section><section class="task-tab" hidden><h3>执行轮次</h3>${table(['执行','状态','模型 / 耗时','用量与费用'],t.runs.map(r=>`<tr><td>${esc(r.id.slice(0,8))}</td><td>${badge(r.status)}<small>${esc(r.error||'')}</small></td><td>${esc(r.model)}<small>${r.seconds??'—'} 秒</small></td><td>输入 ${r.input_tokens??'未知'} / 输出 ${r.output_tokens??'未知'}<small>${r.cost==null?'费用无法核实':r.cost.toFixed(6)+' 元'}</small></td></tr>`).join(''))}<h3>过程事件（不展示模型内部思考）</h3>${t.events.map(e=>`<div class="timeline"><b>${esc(e.action)}</b><small>${stamp(e.at)} · ${esc(nameOf(e.actor))}</small><pre>${esc(e.detail)}</pre></div>`).join('')}</section><section class="task-tab" hidden>${t.artifacts.map(a=>`<details class="artifact" ${a.id===latest?.id?'open':''}><summary>成果 V${a.version} · ${esc(a.origin)} · ${stamp(a.at)}</summary><div class="artifact-links"><a href="/api/tasks/${id}/artifacts/${a.id}">下载 Markdown</a><a href="/api/tasks/${id}/artifacts/${a.id}?format=docx">下载 Word</a></div><p class="muted">格式检查：${(a.checks||[]).map(c=>esc(c.item)+(c.passed?' ✓':' 待补齐')).join('；')||'人工交付，按验收标准审核'}。格式检查不等于事实核验。</p><pre class="report">${esc(a.content)}</pre></details>`).join('')||empty('尚无成果，可以执行任务或人工编辑交付')}${editor&&!['已完成','已取消','待验收'].includes(t.status)?`<label>人工编辑 / 接管交付<textarea id="artifact-content">${esc(latest?.content||'')}</textarea></label><small>保存生成新版本，不覆盖历史；已验收任务须创建修订任务。</small><div class="card-actions"><button onclick="saveArtifact(false)">保存新版本</button><button class="primary" onclick="saveArtifact(true)">保存并提交验收</button></div>`:''}</section><section class="task-tab" hidden>${t.reviews.map(r=>`<div class="file"><b>${esc(r.decision)} · 成果 ${esc(t.artifacts.find(a=>a.id===r.artifact_id)?.version||'')} 版</b><p class="prewrap">${esc(r.note||'按验收标准通过')}</p><small>${esc(nameOf(r.actor))} · ${stamp(r.at)}</small></div>`).join('')||empty('尚无验收记录')}${reviewer&&t.status==='待验收'?`<h3>验收固定成果版本</h3>${checks('逐项确认','review-check',t.criteria.split('\n').filter(Boolean).map((s,i)=>[i,s]))}<label>验收意见（退回必填）<textarea id="review-note"></textarea></label><div class="card-actions"><button onclick="reviewTask(false)">退回修改</button><button class="primary" onclick="reviewTask(true)">验收通过</button></div>`:''}</section><section class="task-tab" hidden><p>采纳状态：${badge(t.feedback)}</p><p class="prewrap">${esc(t.feedback_note)}</p>${editor&&t.status==='已完成'?`<button onclick="feedbackForm()">记录采纳反馈</button>`:''}<h3>后续行动</h3>${actions.map(a=>`<div class="file"><b>${esc(a.name)}</b> ${badge(a.status)}<small>${esc(nameOf(a.owner_id))} · ${esc(a.due)}</small><p class="prewrap">${esc(a.evidence)}</p><button onclick="editAction('${a.id}')">跟进行动</button></div>`).join('')||empty('暂无后续行动')}${editor?`<button onclick="actionForm()">＋ 新增行动</button>`:''}${editor&&t.status==='已完成'?`<button onclick="proposeKnowledge()">成果申请入库</button>`:''}</section><div class="modalfoot task-buttons"><button onclick="closeModal()">关闭</button>${editor&&['草稿','待补充'].includes(t.status)?'<button onclick="doTaskAction(\'submit_task\')">提交任务</button>':''}${editor&&['排队中','进行中'].includes(t.status)&&!t.running?`<button class="primary" onclick="runTask(false)">执行 / 重新执行</button>${t.runs.some(r=>r.status==='待恢复')?'<button onclick="runTask(true)">恢复中断执行</button>':''}${latest?'<button onclick="doTaskAction(\'submit_latest\')">提交最新成果</button>':''}<button onclick="contractForm()">变更 / 改派</button><button onclick="requestInput()">标记待补充</button>`:''}${editor&&!['已完成','已取消'].includes(t.status)?'<button onclick="cancelTask()">取消任务</button>':''}${editor&&t.status==='已完成'?`<button onclick="reviseTask()">创建修订任务</button>`:''}</div>`);$('#dialog').classList.add('wide-dialog');const tabButton=document.querySelectorAll('.detail-tabs button')[selectedTaskTab];if(tabButton)taskTab(selectedTaskTab,tabButton);}catch(e){toast(e.message)}}
function taskTab(i,b){selectedTaskTab=i;document.querySelectorAll('.task-tab').forEach((x,j)=>x.hidden=i!==j);document.querySelectorAll('.detail-tabs button').forEach(x=>x.classList.remove('selected'));b.classList.add('selected')}
async function doTaskAction(action,extra={}){try{const t=currentTask;await api(`/api/tasks/${t.id}/action`,{method:'POST',body:JSON.stringify({action,rev:t.rev,...extra})});await render();await detail(t.id)}catch(e){toast(e.message)}}
function saveArtifact(submit){const content=$('#artifact-content').value;doTaskAction(submit?'submit_artifact':'save_artifact',{content})}
function reviewTask(approved){const boxes=[...document.querySelectorAll('[name="review-check"]')];if(approved&&boxes.some(b=>!b.checked))return toast('请逐项确认验收标准');doTaskAction(approved?'approve':'reject',{artifact_id:currentTask.submitted_id,note:$('#review-note').value,checklist:boxes.map(x=>({item:x.parentElement.textContent,passed:x.checked}))})}
async function runTask(resume){try{const t=currentTask;await api(`/api/tasks/${t.id}/run`,{method:'POST',body:JSON.stringify({rev:t.rev,resume})});await render();await detail(t.id);toast('执行已启动，可关闭详情后继续工作')}catch(e){toast(e.message)}}
function cancelTask(){const t=currentTask;formDialog('取消任务',area('取消原因','note','',true),async f=>{await api(`/api/tasks/${t.id}/action`,{method:'POST',body:JSON.stringify({action:'cancel',rev:t.rev,note:f.get('note')})});closeModal();await render()})}
function contractForm(){const t=currentTask;let addedFiles=[];formDialog('变更任务契约 / 改派',area('目标','goal',t.goal,true)+area('背景与补充材料','input',t.input)+area('验收标准','criteria',t.criteria,true)+select('负责数字员工','employee_id',state.employees.filter(e=>e.status==='在岗').map(e=>[e.id,e.name]),t.employee_id)+field('截止日期','due',t.due,'date',true)+select('验收人','reviewer_id',state.directory.map(u=>[u.id,u.name]),t.reviewer_id)+select('业务负责人','owner_id',state.directory.map(u=>[u.id,u.name]),t.owner_id)+field('费用上限（元，可空）','budget',t.budget??'','number')+'<label>补充输入文件<input type="file" id="extra-files" multiple></label><p id="extra-file-status"></p>'+area('变更原因与确认说明','note','',true),async f=>{const d=Object.fromEntries(f);d.owner_id=Number(d.owner_id);d.reviewer_id=Number(d.reviewer_id);d.budget=d.budget?Number(d.budget):null;d.file_ids=[...t.file_ids,...addedFiles];await api(`/api/tasks/${t.id}/action`,{method:'POST',body:JSON.stringify({...d,action:'revise_contract',rev:t.rev})});closeModal();await render();detail(t.id)});$('#extra-files').onchange=async ev=>{const b=$('#save-button');b.disabled=true;try{for(const file of ev.target.files){const f=new FormData();f.append('file',file);const r=await fetch('/api/upload',{method:'POST',body:f});const d=await r.json();if(!r.ok)throw Error(d.detail);addedFiles.push(d.id);$('#extra-file-status').textContent+=d.name+' 已上传； '}}catch(e){formError(e)}finally{b.disabled=false}}}
function feedbackForm(){const t=currentTask;formDialog('记录业务采纳',select('采纳分类','feedback',['已采纳','部分采纳','未采纳','不适用'].map(x=>[x,x]),t.feedback)+area('用途、理由与结果说明','note',t.feedback_note,true),async f=>{await api(`/api/tasks/${t.id}/action`,{method:'POST',body:JSON.stringify({action:'feedback',rev:t.rev,...Object.fromEntries(f)})});closeModal();await render();detail(t.id)})}
function reviseTask(){const t=currentTask;closeModal();newTask(t.employee_id,'',{title:t.title+'（修订）',goal:t.goal,input:`关联原任务 ${t.id}\n${t.input}`,criteria:t.criteria})}
function actionForm(){const t=currentTask;formDialog('新增后续行动',field('行动名称','name','','text',true)+select('负责人','owner_id',state.directory.map(u=>[u.id,u.name]),currentUser.id)+field('截止日期','due',today(),'date',true),async f=>{const d=Object.fromEntries(f);await api('/api/actions',{method:'POST',body:JSON.stringify({...d,owner_id:Number(d.owner_id),task_id:t.id})});closeModal();await render();detail(t.id)})}
function editAction(id){const a=state.actions.find(a=>a.id===id),tid=a.task_id;formDialog('跟进行动结果',select('状态','status',['待开始','进行中','已完成','已取消'].map(x=>[x,x]),a.status)+area('结果证据（完成时必填）','evidence',a.evidence),async f=>{await api('/api/actions/'+id,{method:'PUT',body:JSON.stringify({...Object.fromEntries(f),rev:a.rev})});closeModal();await render();detail(tid)})}
function proposeKnowledge(){const t=currentTask;const artifact=t.artifacts.find(a=>a.id===t.submitted_id);closeModal();entityForm('knowledge',null,{name:t.title,content:artifact?.content||'',source:`已验收任务 ${t.id} / 成果 ${t.submitted_id}`,source_task_id:t.id})}
function spacesPage(){return head('工作空间','围绕项目组织成员、任务、成果与行动。','＋ 新建空间',"entityForm('spaces')")+`<div class="space-grid">${state.spaces.map(s=>{const ts=state.tasks.filter(t=>t.space_id===s.id);return `<section class="panel"><div class="section-head"><h2>${esc(s.name)}</h2>${badge(s.status||'进行中')}</div><p>${esc(s.goal)}</p><small>负责人 ${esc(nameOf(s.owner_id))} · ${s.members.length} 位成员</small><p>任务 ${ts.length} · 验收完成 ${ts.filter(t=>t.status==='已完成').length}（任务口径，不代表项目整体进度）</p><div class="card-actions"><button onclick="spaceDetail('${s.id}')">进入空间</button>${adminMode()||s.owner_id===currentUser.id?`<button onclick="entityForm('spaces','${s.id}')">成员与归档</button>`:''}</div></section>`}).join('')||empty('暂无工作空间，简单任务也可独立创建')}</div>`}
function spaceDetail(id){const s=state.spaces.find(x=>x.id===id),tasks=state.tasks.filter(t=>t.space_id===id);modal(`<h2>${esc(s.name)}</h2><p class="prewrap">${esc(s.goal)}</p><p>成员：${s.members.map(nameOf).map(esc).join('、')}；负责人 ${esc(nameOf(s.owner_id))}</p><h3>里程碑</h3>${(s.milestones||[]).map((m,i)=>`<div class="file"><b>${esc(m.name)}</b> ${badge(m.status)}<small>${esc(nameOf(m.owner_id))} · ${esc(m.due)}</small><p>${esc(m.evidence||'')}</p>${adminMode()||s.owner_id===currentUser.id?`<button onclick="milestoneForm('${id}',${i})">更新里程碑</button>`:''}</div>`).join('')||empty('暂无里程碑')}${adminMode()||s.owner_id===currentUser.id?`<button onclick="milestoneForm('${id}')">＋ 里程碑</button>`:''}<h3>项目任务</h3>${taskList(tasks)}<h3>材料</h3>${tasks.flatMap(t=>t.file_ids.map(fid=>`<div class="file">${esc(t.title)} · <a href="/api/files/${fid}?task_id=${t.id}">读取材料 ${fid.slice(0,8)}</a><small>按原材料权限校验；空间成员不自动获得下载权限</small></div>`)).join('')||empty('尚无任务材料；创建空间任务时上传并保留来源')}<h3>成果</h3>${tasks.flatMap(t=>t.artifacts.map(a=>`<div class="file"><button class="link" onclick="detail('${t.id}')">${esc(t.title)} · V${a.version}</button><small>${esc(t.status)}</small></div>`)).join('')||empty('暂无成果')}<h3>行动项</h3>${state.actions.filter(a=>tasks.some(t=>t.id===a.task_id)).map(a=>`<div class="file">${esc(a.name)} ${badge(a.status)}<button onclick="editAction('${a.id}')">跟进</button></div>`).join('')||empty('暂无行动')}<div class="modalfoot"><button onclick="closeModal()">关闭</button><button class="primary" onclick="closeModal();spaceFilter='${id}';newTask()">创建空间任务</button></div>`);$('#dialog').classList.add('wide-dialog')}
function knowledgePage(){const ks=state.knowledge.filter(k=>!query||[k.name,k.content,k.source].join(' ').includes(query));return head('知识库','候选知识经过审核发布后，才能作为任务有效依据。','＋ 提交知识',"entityForm('knowledge')")+`<section class="panel">${table(['知识 / 版本','来源','状态 / 有效期','负责人','操作'],ks.map(k=>`<tr><td><button class="link" onclick="knowledgeDetail('${k.id}')">${esc(k.name)}</button><small>V${k.version}</small></td><td>${esc(k.source)}</td><td>${badge(k.status)}<small>${esc(k.expires||'未设置到期日')}</small></td><td>${esc(nameOf(k.owner_id))}</td><td>${adminMode()||k.owner_id===currentUser.id?`<button onclick="entityForm('knowledge','${k.id}')">编辑 / 审核</button>`:''}</td></tr>`).join(''))}</section>`}
function knowledgeDetail(id){const k=state.knowledge.find(k=>k.id===id);modal(`<h2>${esc(k.name)}</h2><p>${badge(k.status)} · V${k.version}</p><p>来源：${esc(k.source)}</p><p>有效期：${esc(k.expires||'未设置')}；审核：${esc(k.review_note||'待审核')}</p><pre class="report">${esc(k.content)}</pre><details><summary>历史版本（${k.history?.length||0}）</summary>${(k.history||[]).map(h=>`<div class="file">V${h.version} · ${badge(h.status)}<pre>${esc(h.content)}</pre></div>`).join('')}</details><div class="modalfoot"><button onclick="closeModal()">关闭</button></div>`)}
