function searchPage(q){query=q;const groups=[['任务',state.tasks.filter(t=>[t.title,t.goal].join(' ').includes(q)),t=>`<button class="link" onclick="detail('${t.id}')">${esc(t.title)}</button>`],['数字员工',state.employees.filter(e=>[e.name,e.mission].join(' ').includes(q)),e=>`<button class="link" onclick="employeeDetail('${e.id}')">${esc(e.name)}</button>`],['知识',state.knowledge.filter(k=>[k.name,k.content].join(' ').includes(q)),k=>`<button class="link" onclick="knowledgeDetail('${k.id}')">${esc(k.name)} · V${k.version}</button>`],['成果',state.tasks.flatMap(t=>t.artifacts.map(a=>({...a,tid:t.id,title:t.title}))).filter(a=>[a.title,a.content].join(' ').includes(q)),a=>`<button class="link" onclick="detail('${a.tid}')">${esc(a.title)} · V${a.version}</button>`],['工具',state.tools.filter(t=>[t.name,t.description].join(' ').includes(q)),t=>`<b>${esc(t.name)}</b><small>${esc(t.description)}</small>`]];$('#content').innerHTML=head('全局搜索',`当前授权范围，关键词：${q}`)+groups.map(([title,list,draw])=>`<section class="panel"><h2>${title} · ${list.length}</h2>${list.map(o=>`<div class="file">${draw(o)}</div>`).join('')||empty('无匹配结果')}</section>`).join('')}
