setInterval(async()=>{if(!currentUser||document.hidden)return;try{const old=state;await refresh();if(state.tasks.some(t=>t.running)||old?.tasks.some(t=>t.running)){if(!$('#dialog').open)await render();else if(currentTask&&$('#dialog .task-heading')){if(currentTask.running&&!document.activeElement?.matches('textarea,input,select')){await detail(currentTask.id);return;}const status=$('#dialogBody .task-heading small');if(status)status.textContent='执行进度自动更新中；点击刷新查看过程与成果';}}const unread=state.notices.filter(n=>!n.read).length;$('#notice').innerHTML=svgIcon('bell')+(unread?`<i>${unread}</i>`:'')}catch{}},5000);

let activeChat=null;
function clarify(id){activeChat={employee_id:id,messages:[]};drawChat()}
function drawChat(){const c=activeChat;modal(`<h2>${esc(employeeOf(c.employee_id)?.name)} · 需求澄清</h2><div class="noticebar">澄清结果不会自动创建任务，转入表单后由你确认目标与验收标准。</div><div class="chat-messages">${c.messages.map(m=>`<div class="chat-message ${m.role}"><b>${m.role==='user'?'我':'数字员工'}</b><p class="prewrap">${esc(m.content)}</p></div>`).join('')||empty('说明你希望完成的工作，员工会帮助澄清范围与材料。')}</div><form id="chat-form"><label>你的需求<textarea id="chat-input" required maxlength="8000"></textarea></label><p id="chat-error" class="error"></p><div class="modalfoot"><button type="button" onclick="manualClarify('${c.employee_id}')">直接填写任务</button><button type="button" onclick="chatToTask()" ${!c.messages.length?'disabled':''}>确认并转任务草稿</button><button class="primary">发送</button></div></form>`);$('#chat-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button.primary');button.disabled=true;const text=$('#chat-input').value;try{const r=await api('/api/clarify',{method:'POST',body:JSON.stringify({employee_id:c.employee_id,chat_id:c.id,message:text})});activeChat=r;drawChat()}catch(err){$('#chat-error').textContent=err.message}finally{if(button.isConnected)button.disabled=false}}}
function chatToTask(){const c=activeChat;closeModal();newTask(c.employee_id,'',{goal:c.messages.filter(m=>m.role==='user').map(m=>m.content).join('\n'),input:'需求澄清记录（请核对）：\n'+c.messages.map(m=>(m.role==='user'?'用户：':'员工：')+m.content).join('\n')})}

function milestoneForm(id,index){const s=state.spaces.find(x=>x.id===id),m=s.milestones?.[index]||{};formDialog('项目里程碑',field('里程碑名称','name',m.name||'','text',true)+select('负责人','owner_id',state.directory.map(u=>[u.id,u.name]),m.owner_id||currentUser.id)+field('截止日期','due',m.due||today(),'date',true)+select('状态','status',['待开始','进行中','已完成','已取消'].map(x=>[x,x]),m.status||'待开始')+area('结果证据（完成必填）','evidence',m.evidence||''),async f=>{const d=Object.fromEntries(f);d.owner_id=Number(d.owner_id);const milestones=[...(s.milestones||[])];if(index==null)milestones.push(d);else milestones[index]=d;await api('/api/entities/spaces/'+id,{method:'PUT',body:JSON.stringify({...s,milestones})});closeModal();await render();spaceDetail(id)})}

function legacyImport(){let legacy=[];try{legacy=JSON.parse(localStorage.getItem('huaxia-tasks-v1')||'[]')}catch{}const candidates=legacy.filter(t=>!String(t.input||'').startsWith('示例任务')||t.draft&&!String(t.draft).startsWith('示例交付'));if(!candidates.length)return toast('未发现可导入的非示例任务；旧浏览器记录未被修改');formDialog('导入旧浏览器任务',`<div class="noticebar">只导入你明确选择的记录。原始浏览器数据保留；原验收状态不视为正式审批，有成果时保存为待重新审核的版本。</div>${checks('选择旧任务','legacy',candidates.map(t=>[String(t.id),t.title]))}${select('导入后负责数字员工','employee_id',state.employees.filter(e=>e.status==='在岗').map(e=>[e.id,e.name]))}<p id="import-progress"></p>`,async f=>{const chosen=f.getAll('legacy');if(!chosen.length)throw Error('请至少选择一项');for(const key of chosen){const old=candidates.find(t=>String(t.id)===key);const payload={title:old.title,goal:'导入原型任务：'+old.title,input:(old.input||'')+'\n原型历史记录（非正式审批）：\n'+JSON.stringify(old.logs||[]),criteria:old.criteria||'人工重新核验交付',due:old.due||today(),past_due_reason:'从旧浏览器记录导入，需重新确认',employee_id:f.get('employee_id'),reviewer_id:currentUser.id,owner_id:currentUser.id};const t=await api('/api/tasks',{method:'POST',headers:{'Idempotency-Key':'legacy-'+currentUser.id+'-'+key},body:JSON.stringify(payload)});if(old.draft&&t.artifacts.length===0)await api('/api/tasks/'+t.id+'/action',{method:'POST',body:JSON.stringify({action:'save_artifact',rev:t.rev,content:old.draft})});$('#import-progress').textContent='已导入：'+old.title}closeModal();await render();toast('导入完成，旧记录仍保留')})}

function requestInput(){const t=currentTask;formDialog('标记待补充',area('缺失材料或需要确认的问题','note','',true),async f=>{await api('/api/tasks/'+t.id+'/action',{method:'POST',body:JSON.stringify({action:'request_input',rev:t.rev,note:f.get('note')})});closeModal();await render();detail(t.id)})}

function applyHomeDesign(){const layout=$('.workspace-layout'),main=layout?.firstElementChild;if(!main)return;const stats=$('#content>.metric-grid');const recent=[...main.querySelectorAll(':scope>.panel')].find(p=>p.querySelector('h2')?.textContent==='近期任务进展');if(stats&&recent){const row=document.createElement('div');row.className='home-task-row';recent.before(row);row.append(recent);const panel=document.createElement('section');panel.className='panel home-overview';panel.innerHTML='<h2>任务数据概览</h2>';panel.append(stats);const counts=roleNames.map(role=>state.tasks.filter(t=>(employeeOf(t.employee_id)?.role_type||t.employee_snapshot.role_type)===role).length);const total=state.tasks.length,colors=['#087bff','#00ad87','#ff961f','#8551ef'];let angle=0;const stops=counts.map((count,i)=>{const start=angle;angle+=total?count/total*360:0;return `${colors[i]} ${start}deg ${angle}deg`});const chart=document.createElement('div');chart.className='home-chart';chart.innerHTML=`<div class="real-donut" style="background:${total?'conic-gradient('+stops.join(',')+')':'#e4edf7'}"><div><b>${total}</b><small>总任务数</small></div></div><div>${roleNames.map((r,i)=>`<p><i style="background:${colors[i]}"></i>${esc(r)}<span>${total?Math.round(counts[i]/total*100)+'%':'—'}</span></p>`).join('')}</div>`;panel.append(chart);if(!total)panel.insertAdjacentHTML('beforeend','<small class="muted">暂无任务，不显示虚构分布</small>');row.append(panel)}const hero=$('.system-hero');if(hero){hero.innerHTML='<img class="design-hero-art" src="assets/prototype-reference.png" alt="数字员工，让专业创造更大价值；研究更深入、需求更清晰、交付更高效、决策更有依据">';hero.classList.add('reference-hero')}const resources=main.querySelector('.resource-grid');resources?.classList.toggle('resources-empty',state.knowledge.filter(k=>k.status==='已发布').length===0);}

const employeeAvatarOptions=[['portrait-01','知行'],['portrait-02','明思'],['portrait-03','笃行'],['portrait-04','慧析'],['portrait-05','远见'],['portrait-06','悦知'],['portrait-07','清和'],['portrait-08','睿达']];
function avatarId(e){return employeeAvatarOptions.some(a=>a[0]===e.avatar_id)?e.avatar_id:'portrait-'+String(Math.max(0,roleNames.indexOf(e.role_type))+1).padStart(2,'0')}
function employeeAvatar(e){return `<img class="employee-avatar" src="assets/avatars/${avatarId(e)}.svg" alt="${esc(e.name)}头像" width="64" height="64">`}
function avatarPicker(e){const selected=avatarId(e);return `<fieldset class="avatar-picker"><legend>数字员工头像 · 上岗形象</legend><p class="muted">选择头像后保存，首页、员工目录与档案同步使用；头像名称只是形象代号，不改变员工姓名。</p><div class="avatar-options">${employeeAvatarOptions.map(([id,name])=>`<label class="avatar-option"><input type="radio" name="avatar_id" value="${id}" ${selected===id?'checked':''} required><span><img src="assets/avatars/${id}.svg" alt="" width="64" height="64"><b>${name}</b><small>选择此形象</small></span></label>`).join('')}</div></fieldset>`}
